package com.novacommerce.order.domain.order; import jakarta.persistence.*; import java.math.BigDecimal; import java.util.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="order_items") public class OrderItem {@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="order_id",nullable=false)private CustomerOrder order;@Column(name="variant_id")private UUID variantId;@Column(name="product_id")private UUID productId;@Column(name="product_name")private String productName;@Column(name="product_slug")private String productSlug;@Column(name="variant_name")private String variantName;private String sku;@JdbcTypeCode(SqlTypes.JSON)@Column(columnDefinition="jsonb")private Map<String,String> attributes=new LinkedHashMap<>();private long quantity;@Column(name="unit_price",precision=19,scale=2)private BigDecimal unitPrice;@Column(name="line_total",precision=19,scale=2)private BigDecimal lineTotal;private String currency;protected OrderItem(){}public OrderItem(CustomerOrder o,UUID variant,UUID product,String productName,String slug,String variantName,String sku,Map<String,String> attrs,long q,BigDecimal price,String currency){id=UUID.randomUUID();order=o;variantId=variant;productId=product;this.productName=productName;productSlug=slug;this.variantName=variantName;this.sku=sku;attributes.putAll(attrs);quantity=q;unitPrice=price;lineTotal=price.multiply(BigDecimal.valueOf(q));this.currency=currency;}public UUID getId(){return id;}public UUID getVariantId(){return variantId;}public UUID getProductId(){return productId;}public String getProductName(){return productName;}public String getProductSlug(){return productSlug;}public String getVariantName(){return variantName;}public String getSku(){return sku;}public Map<String,String> getAttributes(){return Map.copyOf(attributes);}public long getQuantity(){return quantity;}public BigDecimal getUnitPrice(){return unitPrice;}public BigDecimal getLineTotal(){return lineTotal;}public String getCurrency(){return currency;}}
